# Export functions
def to_txt(arr):

    # Function to write ANY structure to a txt file 
    
    # Write the output to txt files
   
    candidates_file = "tests/txt_output/to_txt_output.txt"
    with open(candidates_file, 'w') as f:
        line = '['
        for sublist in arr:
            sublist_str = str(sublist)
            if len(line) + len(sublist_str) <= 160:
                if line[-1] == '[':
                    line += sublist_str
                else:
                    line += ', ' + sublist_str
            else:
                f.write(line + ',\n')
                line = '    ' + sublist_str
        if line != '[':
            f.write(line + '\n]')
        else:
            f.write('[]\n')
    print()
    print('Structure has been written to to_txt_output.txt')
    print()


def to_python(filename):

    # Retrieve the contents of a txt file

    # Open the file in read mode
    with open('tests/txt_output/' + filename, 'r') as file:
        # Read the contents of the file
        content = file.read().strip()
        
        # Convert the string to a Python list using eval (only if you trust the source)
        python_list = eval(content)

    return python_list


# PDB Functions
def exportParsed(parsed_data, filename):

    # Takes parsed data, exports data to txt file.
    # filename: the file name to be given to the new txt file

    filepath = os.path.join(DIR_LOCAL, filename) # complete file path

    # Open the file in write mode
    with open(filepath, 'w') as file:
        # Iterate over each sublist in the main list
        for sublist in parsed_data:
            # Convert each sublist to a string, joining the elements with commas
            line = ','.join(map(str, sublist))
            # Write the string to the file
            file.write(line + '\n')


def parsed(filename):
    
    # Takes a file data that has already been parsed, formats it, and imports.
    # Returns a list with format of typical parsed file.

    filepath = os.path.join(DIR_LOCAL, filename) # complete file path
    
    data = [] # For reconstructed list.

    # Open the file in read mode
    with open(filepath, 'r') as file:
        # Iterate over each line in the file
        for line in file:
            # Split the line into individual elements based on commas
            elements = line.strip().split(',')
            # Convert each element from string to float and append to the data list
            data.append([float(element) for element in elements])
    
    output=[] # Will hold restructured data

    for i in range(len(data[0])):
        output.append([data[0][i], data[1][i], data[2][i]])

    return output


