# Plot Functions
def plot_1D(y):
    # Plots a Numpy array of 1D points [1.1  6.3  8.2  ...]

    x = [i for i in range(len(y))] # [0,1,2,3...]

    # Plotting
    plt.plot(x, y, marker='o', linestyle='-', color='b', label='Data')  # Adjust linestyle, marker, and color as needed
    plt.xlabel('x')
    plt.ylabel('y')
    plt.grid(True)  # Optional: add grid
    plt.show() #"""


def plot_2D(x,y):
    # Plots a Numpy array of 2D points [[3, 1.1]  [6.3, 4]  [5, 8.2]  ...]

    # Sort the x-values and rearrange y-values accordingly
    sorted_indices = np.argsort(x)  # Get the indices that would sort x
    x_sorted = x[sorted_indices]  # Sort x-values
    y_sorted = y[sorted_indices]  # Rearrange y-values to match sorted x-values

    # Plotting
    plt.plot(x_sorted, y_sorted, marker='o', linestyle='-', color='b', label='Data')  # Adjust linestyle, marker, and color as needed
    plt.xlabel('x')
    plt.ylabel('y')
    plt.grid(True)  # Optional: add grid
    plt.show() #"""


def plot_multiple(plot_list):
    
    # Plots multiple scatter plots
    # scatter_list: Python list of sublists. Each sublist is a list of points.
    
    # Create a new figure for 3D plot
    fig = plt.figure()
    ax = fig.add_subplot(111, projection='3d')

    # Labeling the axes
    ax.set_xlabel('x')
    ax.set_ylabel('y')
    ax.set_zlabel('z')

    ax.set_title('3D Scatter Plot') # Title of the plot

    # Generate colors from a colormap
    colors = cm.viridis(np.linspace(0, 1, len(plot_list)))

    for i, list in enumerate(plot_list):
        # Sample data for 3D points
        x = [point[0] for point in list]
        y = [point[1] for point in list]
        z = [point[2] for point in list]

        # Plotting the points
        ax.plot(x, y, z, color=colors[i], marker='o', label=i)

    #plt.legend(range(len(scatter_list))) # Add a legend
    plt.legend() # Add a legend

    plt.show() # Show plot


def plot_protein_voxels_l(p_list):
    
    # Plots voxels of multiple proteins.
    # Input is a list of (n,3) np arrays.
    # p_list: Python List of numpy arrays. 'a', 'b', etc.
    # Note: Because of input shape, this can now only test the function find_p.

    # Plot figure
    fig = plt.figure()
    ax = fig.add_subplot(111, projection='3d')

    ax.set_xlabel('x')
    ax.set_ylabel('y')
    ax.set_zlabel('z')

    # Generate colors from a colormap
    colors = cm.viridis_r(np.linspace(0, 1, len(p_list)))
    colors[:, 3] = 0.9 # Change alpha, the color transparency value

    for p_index, p in enumerate(p_list):
        v_p = np.min(p, axis=0) # Shift vector
        p_shifted = p - v_p # matplotlib voxel function requires shift to first octant

        axes = [int(value)+1 for value in np.max(p_shifted,axis=0)] # Create axis

        data = np.zeros(axes, dtype=bool) # Create Data

        for voxel in p_shifted:
            i,j,k = voxel.astype(int)
            data[i,j,k] = True

        x, y, z = np.indices(np.array(axes) + 1) - 0.5 # Coordinates for shifted p

        # Add the voxels
        ax.voxels(x+v_p[0], y+v_p[1], z+v_p[2], data, facecolors=colors[p_index])

    # Aspect Ratio
    max_val = np.max([np.max(p) for p in p_list]) # Values to adjust the aspect ratio
    min_val = np.min([np.min(p) for p in p_list])
    ax.set_xlim(min_val, max_val)
    ax.set_ylim(min_val, max_val)
    ax.set_zlim(min_val+0.4, max_val-0.4) # z must be manually corrected

    # Creating custom legend handles
    legend_labels = ['Protein ' + str(i+1) for i in range(len(p_list))]
    legend_handles = []
    for color in colors:
        legend_handles.append(plt.Line2D([0], [0], marker='o', color='w', markerfacecolor=color, markersize=10))

    # Adding legend with custom handles and labels
    plt.legend(legend_handles, legend_labels, loc='best')

    plt.show()


def plot_protein_voxels(p_list, s_list):
    
    # Plots voxels of multiple proteins.
    # p_list: Python List of multi-dim numpy arrays. 'a', 'b', etc.
    # s_list: Python List of shift vectors for 'a', 'b', etc.

    # Plot figure
    fig = plt.figure()
    ax = fig.add_subplot(111, projection='3d')

    ax.set_xlabel('x')
    ax.set_ylabel('y')
    ax.set_zlabel('z')

    # Generate colors from a colormap
    colors = cm.viridis_r(np.linspace(0, 1, len(p_list)))
    colors[:, 3] = 0.9 # Change alpha, the color transparency value

    for p_index, p in enumerate(p_list):
        
        axes = p.shape # Create axis
        data = np.zeros(axes, dtype=bool) # Create Data

        for i in range(axes[0]):
            for j in range(axes[1]):
                for k in range(axes[2]):
                    if p[i,j,k] != 0:
                        data[i,j,k] = True

        x, y, z = np.indices(np.array(axes) + 1) - 0.5 # Coordinates for shifted p

        # Add the voxels
        v_s = s_list[p_index] # Shift vector for this particular protein
        ax.voxels(x+v_s[0], y+v_s[1], z+v_s[2], data, facecolors=colors[p_index])

    # Aspect Ratio
    extrema = []
    for i in range(len(p_list)):
        extrema.append(s_list[i])
        extrema.append(p_list[i].shape + s_list[i] - [1,1,1])
    # append min, max for every protein
    
    v_min, v_max = np.min(extrema, axis=0), np.max(extrema, axis=0)

    ax.set_xlim([v_min[0], v_max[0]])
    ax.set_ylim([v_min[1], v_max[1]])
    ax.set_zlim([v_min[2], v_max[2]])
    # Set limits for x, y, z axes

    ax.set_box_aspect(v_max - v_min)
    # Adjust aspect ratio to be equal

    # Creating custom legend handles
    legend_labels = ['Protein ' + str(i+1) for i in range(len(p_list))]
    legend_handles = []
    for color in colors:
        legend_handles.append(plt.Line2D([0], [0], marker='o', color='w', markerfacecolor=color, markersize=10))

    # Adding legend with custom handles and labels
    plt.legend(legend_handles, legend_labels, loc='best')

    plt.show()


def plot_protein_voxels_s(p_list, s_list):
    
    # Plots voxels of multiple proteins. Includes surface
    # p_list: Python List of multi-dim numpy arrays. 'a', 'b', etc.
    # s_list: Python List of shift vectors for 'a', 'b', etc.

    # Plot figure
    fig = plt.figure()
    ax = fig.add_subplot(111, projection='3d')

    ax.set_xlabel('x')
    ax.set_ylabel('y')
    ax.set_zlabel('z')

    # Generate colors from a colormap
    colors = cm.viridis_r(np.linspace(0, 0.5, len(p_list)))
    colors[:, 3] = 1 # Change alpha, the color transparency value
    s_color = [0,0,0,0.3] # Color for surface voxels

    all_vox = [] # will hold all voxel values to determine plot limits
    for p_index, p in enumerate(p_list):

        axes = p.shape # Create axis
        data_in = np.zeros(axes, dtype=bool) # Create Data for inside protein
        data_s = np.zeros(axes, dtype=bool) # Create Data for surface

        for i in range(axes[0]):
            for j in range(axes[1]):
                for k in range(axes[2]):
                    if p[i,j,k] == 1:
                        data_s[i,j,k] = True
                    elif p[i,j,k] == c.RHO or p[i,j,k] == c.DEL_B: 
                        data_in[i,j,k] = True

        x, y, z = np.indices(np.array(axes) + 1) - 0.5 # Coordinates for shifted p

        # Add the voxels
        v_s = s_list[p_index] # Shift vector for this particular protein
        ax.voxels(x+v_s[0], y+v_s[1], z+v_s[2], data_in, facecolors=colors[p_index])
        ax.voxels(x+v_s[0], y+v_s[1], z+v_s[2], data_s, facecolors=s_color)
        all_vox.append([x+v_s[0], y+v_s[1], z+v_s[2]])

    # Aspect Ratio
    extrema = []
    for i in range(len(p_list)):
        extrema.append(s_list[i])
        extrema.append(p_list[i].shape + s_list[i] - [1,1,1])
    # append min, max for every protein
    
    v_min, v_max = np.min(extrema, axis=0), np.max(extrema, axis=0)

    ax.set_xlim([v_min[0], v_max[0]])
    ax.set_ylim([v_min[1], v_max[1]])
    ax.set_zlim([v_min[2], v_max[2]])
    # Set limits for x, y, z axes

    ax.set_box_aspect(v_max - v_min)
    # Adjust aspect ratio to be equal

    # Creating custom legend handles
    legend_labels = ['Protein ' + str(i+1) for i in range(len(p_list))]
    legend_handles = []
    for color in colors:
        legend_handles.append(plt.Line2D([0], [0], marker='o', color='w', markerfacecolor=color, markersize=10))

    # Adding legend with custom handles and labels
    plt.legend(legend_handles, legend_labels, loc='best')

    plt.show()


def plot_output(a_c, b_c, e_angles, v_shift):

    # Plots the final product. It applies the steps of the user:
    # 1. Rotate coordinates. 2. Shift coordinates.
    # These new b coordinates will match the coordinates used in the algorithm.

    b_c_out = rotation.utils.e_rotate(e_angles, b_c) + v_shift # New b_c coordinates from output
    b_out = tests.old.to_voxels.protein_voxels(b_c_out, 'discrimination') # voxels that comprise 'b_out'
    b = tests.old.to_voxels.protein_voxels(b_c, 'discrimination') # voxels that comprise native 'b'
    a = tests.old.to_voxels.protein_voxels(a_c, 'discrimination') # voxels that comprise 'a'

    plot_protein_voxels_l([a, b, b_out])


